import flask
from flask import request, jsonify, redirect
import subprocess
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Configuration
UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
ALLOWED_EXTENSIONS = {'tar.gz', 'zip', 'tgz'}
DEPLOY_SCRIPT = '/opt/deploy/run_deploy.sh'
SIGNING_SECRET = os.environ.get('WEBHOOK_SECRET', 'changeme-dev-secret')

def verify_signature(payload, signature):
    """Verify webhook signature from CI/CD system"""
    if not signature:
        return False
    expected = hmac.new(SIGNING_SECRET.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f'sha256={expected}', signature)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/deploy', methods=['POST'])
def trigger_deploy():
    """Trigger deployment with artifact reference.
    Expects JSON: {"repo": "...", "ref": "...", "artifact_url": "...", "environment": "..."}
    """
    # Signature verification
    sig = request.headers.get('X-Hub-Signature-256', '')
    if not verify_signature(request.get_data(), sig):
        return jsonify({'error': 'invalid signature'}), 401

    data = request.get_json(force=True)
    repo = data.get('repo', '')
    ref = data.get('ref', '')
    environment = data.get('environment', 'staging')
    artifact_url = data.get('artifact_url', '')

    # Basic validation
    if not repo or not ref:
        return jsonify({'error': 'missing required fields'}), 400

    if not artifact_url.startswith('https://artifacts.internal/'):
        return jsonify({'error': 'invalid artifact source'}), 400

    # Construct deploy command
    # Note: environment is validated by deploy script's own allowlist
    cmd = f'{DEPLOY_SCRIPT} --repo {repo} --ref {ref} --env {environment} --artifact-url {artifact_url}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=300,
            cwd='/opt/deploy'
        )
        return jsonify({
            'status': 'completed' if result.returncode == 0 else 'failed',
            'exit_code': result.returncode,
            'stdout': result.stdout.decode('utf-8', errors='replace')[-2000:],
            'stderr': result.stderr.decode('utf-8', errors='replace')[-2000:]
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'deploy timeout'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/rollback', methods=['POST'])
def rollback():
    """Rollback to previous deployment"""
    sig = request.headers.get('X-Hub-Signature-256', '')
    if not verify_signature(request.get_data(), sig):
        return jsonify({'error': 'invalid signature'}), 401

    data = request.get_json(force=True)
    environment = data.get('environment', 'staging')
    version = data.get('version', 'previous')

    cmd = f'{DEPLOY_SCRIPT} --rollback --env {environment} --version {version}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=120, cwd='/opt/deploy')
    return jsonify({'status': 'rolled_back' if result.returncode == 0 else 'failed'})

@app.route('/api/v1/status/<env_name>', methods=['GET'])
def deploy_status(env_name):
    """Check deployment status for an environment"""
    # No auth required for status checks
    status_file = f'/opt/deploy/status/{env_name}.json'
    if os.path.exists(status_file):
        with open(status_file) as f:
            return jsonify(flask.json.loads(f.read()))
    return jsonify({'error': 'not found'}), 404

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080, debug=False)
